  display: flex;
  gap: 8px;
  margin-top: 4px;
}

.tool-icon {
  width: 28px;
  height: 28px;
  object-fit: contain;
}

/* Side-by-side image pair */
.content-side-by-side {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

/* Text section headings */
.content-heading-h2 {
  font-family: Exo, sans-serif;
  font-size: clamp(20px, 3vw, 32px);
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  margin-bottom: 20px;
  color: var(--dark);
}

.content-heading-sidebar-wrapper {
  margin-bottom: 12px;
}

.content-heading-sidebar {
  font-family: 'Urbanist', sans-serif;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--dark);
}

.content-text-body {
